fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Check if the input arrays are empty
    if a.is_empty() || b.is_empty() {
        return Vec::new(); // Return an empty vector if either input is empty
    }

    // Create a new vector to store the results
    let mut result = Vec::with_capacity(a.len());

    // Iterate through both arrays and compare elements
    for (x, y) in a.iter().zip(b.iter()) {
        result.push(x < y); // Push the result of the comparison
    }

    result // Return the resulting boolean vector
}